-- Spec 014: each catalog has a default category (Category.isDefault).
-- The schema is not generated by Hibernate (ddl-auto=none), so apply this to MariaDB by hand.
ALTER TABLE categories
    ADD COLUMN is_default BOOLEAN NOT NULL DEFAULT FALSE;

-- Existing catalogs and uncategorized assets don't need a data migration: the app creates a
-- catalog's default category the first time it is needed, and assigns it to an asset without
-- categories the next time that asset is saved.
